files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #111111;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #111111;
  --vt-accent-ink: #c12828;
  --vt-accent-on-deep: #fdb52d;
  --vt-line: rgba(17, 17, 17, 0.14);
  --font-display: 'Fira Sans Condensed', 'Arial', sans-serif;
  --font-body: 'Manrope', 'Arial', sans-serif;
  min-height: 100%;
  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: var(--font-body);
  line-height: 1.6;
  scroll-behavior: smooth;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root a:hover {
  color: var(--vt-accent-ink);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent-ink);
  outline-offset: 2px;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 700;
  line-height: 1.1;
  color: var(--vt-ink);
}

.root :where(p) {
  margin: 0;
}

.root :where(img) {
  display: block;
  max-width: 100%;
}

.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 280px;
  z-index: 50;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 40px;
  padding: 32px 24px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-right: 1px solid var(--vt-line);
}

.logo {
  display: block;
}

.brand {
  display: block;
}

.navLinks {
  display: flex;
  flex-direction: column;
  gap: 18px;
  text-align: center;
}

.navLinks a {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--vt-on-accent);
  padding: 6px 10px;
}

.navLinks a:hover {
  color: var(--vt-on-deep);
}

.navLinks a:focus-visible {
  outline-color: var(--vt-on-accent);
}

.main {
  margin-left: 280px;
}

.hero {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 680px;
  padding: 80px;
  border-bottom: 12px solid var(--vt-accent);
  overflow: hidden;
  color: var(--vt-on-deep);
}

.heroBg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, var(--vt-accent-on-deep) 0%, var(--vt-accent-ink) 100%);
  opacity: 0.65;
}

.heroContent {
  position: relative;
  z-index: 1;
  max-width: 640px;
}

.heroKicker {
  font-size: 13px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: 16px;
  opacity: 0.9;
}

.heroTitle {
  color: var(--vt-on-deep);
  font-size: clamp(48px, 8vw, 88px);
  text-transform: uppercase;
  line-height: 1;
  margin-bottom: 18px;
}

.heroText {
  color: var(--vt-on-deep);
  font-size: 18px;
  max-width: 420px;
  margin-bottom: 32px;
  opacity: 0.95;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.buttonGhost {
  border: 2px solid var(--vt-on-deep);
  color: var(--vt-on-deep);
  padding: 12px 24px;
  border-radius: 100px;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.buttonGhost:hover {
  background: var(--vt-on-deep);
  color: var(--vt-accent-ink);
}

.buttonSolid {
  background: var(--vt-accent-ink);
  border: 2px solid var(--vt-accent-ink);
  color: var(--vt-on-deep);
  padding: 12px 24px;
  border-radius: 100px;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.buttonSolid:hover {
  background: var(--vt-accent-on-deep);
  border-color: var(--vt-accent-on-deep);
  color: var(--vt-on-accent);
}

.section {
  padding: 100px 48px;
}

.sectionAlt {
  background: var(--vt-surface-2);
  padding: 100px 48px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
}

.eyebrow {
  font-size: 13px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--vt-accent-ink);
  margin-bottom: 12px;
}

.title {
  font-size: clamp(34px, 5vw, 54px);
  text-transform: uppercase;
  margin-bottom: 48px;
}

.storyGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.storyMedia {
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 24px;
}

.storyImage {
  width: 100%;
  height: 400px;
  object-fit: cover;
  border-radius: 20px;
  transform: rotate(4deg);
}

.storyBody .title {
  margin-bottom: 24px;
}

.storyText p {
  color: var(--vt-ink-soft);
  margin-bottom: 16px;
}

.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.card {
  border-radius: 20px;
  overflow: hidden;
  background: var(--vt-surface);
  border: 1px solid var(--vt-line);
}

.cardMedia {
  position: relative;
  background: var(--vt-surface-deep);
}

.cardImage {
  width: 100%;
  height: 340px;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.card:hover .cardImage {
  transform: scale(1.05);
}

.pill {
  position: absolute;
  top: 16px;
  right: 16px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  font-size: 12px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: 100px;
}

.duration {
  position: absolute;
  top: 16px;
  left: 16px;
  background: var(--vt-accent-ink);
  color: var(--vt-on-deep);
  font-size: 12px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: 100px;
}

.cardBody {
  padding: 20px;
}

.cardTitle {
  font-size: 24px;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.cardDesc {
  color: var(--vt-ink-soft);
  font-size: 14px;
}

.priceGrid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 64px;
  align-items: center;
}

.priceListBlock {
  min-width: 0;
}

.priceList {
  margin-top: 8px;
}

.priceRow {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 16px 0;
  border-bottom: 1px solid var(--vt-line);
}

.priceRow:last-child {
  border-bottom: none;
}

.priceName {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--vt-ink);
  white-space: nowrap;
}

.divider {
  flex: 1;
  border-bottom: 2px dotted var(--vt-ink-soft);
  transform: translateY(-4px);
}

.priceValue {
  color: var(--vt-accent-ink);
  font-size: 20px;
  white-space: nowrap;
}

.priceMedia {
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 24px;
}

.priceImage {
  width: 100%;
  height: 400px;
  object-fit: cover;
  border-radius: 20px;
  transform: rotate(4deg);
}

.contact {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
}

.contactHeader {
  padding: 80px 48px 0;
}

.titleLight {
  color: var(--vt-on-deep);
  font-size: clamp(34px, 5vw, 54px);
  text-transform: uppercase;
  text-align: center;
  margin-bottom: 48px;
}

.contactGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  padding-bottom: 64px;
}

.contactHeading {
  color: var(--vt-on-deep);
  font-size: 24px;
  margin-bottom: 16px;
}

.contactLine {
  margin-bottom: 10px;
}

.contactLine a {
  color: var(--vt-accent-on-deep);
}

.contactLine a:hover {
  color: var(--vt-on-deep);
}

.social {
  margin-top: 16px;
}

.areas {
  color: var(--vt-on-deep);
  opacity: 0.75;
  max-width: 360px;
  margin-top: 16px;
}

.hoursCard {
  background: var(--vt-accent-ink);
  border-radius: 20px;
  padding: 20px;
  transform: rotate(2deg);
}

.hoursInner {
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 28px 32px;
  transform: rotate(-2deg);
}

.hoursTitle {
  color: var(--vt-on-accent);
  text-transform: uppercase;
  font-size: 18px;
  margin-bottom: 8px;
}

.hoursText {
  color: var(--vt-on-accent);
  font-size: 20px;
  font-weight: 700;
}

.footer {
  border-top: 1px solid var(--vt-line);
  padding: 48px;
}

.footerTop {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
  font-size: 14px;
  color: var(--vt-ink-soft);
  margin-bottom: 12px;
}

.footerPostcode {
  color: var(--vt-ink-soft);
  font-size: 14px;
  margin-top: 8px;
}

@media (max-width: 991px) {
  .sidebar {
    position: static;
    width: 100%;
    height: auto;
    flex-direction: row;
    justify-content: space-between;
    padding: 16px 24px;
    border-right: none;
    border-bottom: 1px solid var(--vt-line);
  }

  .navLinks {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 12px;
    justify-content: flex-end;
  }

  .main {
    margin-left: 0;
  }

  .hero {
    min-height: 520px;
    padding: 48px 24px;
  }

  .section,
  .sectionAlt {
    padding: 64px 24px;
  }

  .storyGrid,
  .priceGrid,
  .contactGrid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .servicesGrid {
    grid-template-columns: 1fr;
  }

  .storyImage,
  .priceImage {
    height: 300px;
  }

  .contactHeader {
    padding: 64px 24px 0;
  }

  .footer {
    padding: 32px 24px;
  }
}

@media (max-width: 560px) {
  .sidebar {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
  }

  .navLinks {
    justify-content: flex-start;
  }

  .hero {
    padding: 40px 20px;
  }

  .heroTitle {
    font-size: 40px;
  }
}
